/// The code of a token of a kind, which is not in [`TOKENS`], followed by its text.
pub(super) const TOKEN_OTHER: (u32, u8) = (0b1111111111111, 13);

/// The code of the end of a token text.
pub(super) const TEXT_END: (u32, u8) = (0b010, 3);

/// The code of a character, which is not in [`CHARS`], followed by its code point.
pub(super) const TEXT_OTHER: (u32, u8) = (0b11111111111110, 14);
